#pragma once

#include <cstdint>
#include <span>
#include <string>
#include <string_view>

#include "cuervo/brand/brand_tokens.hpp" // generated by cmake/Brand.cmake
#include "cuervo/rhi/rhi.hpp"

// The Cuervo brand in the engine (DESIGN.md 4.16, milestone 8.1): the light
// (Bone) and dark (Raven) themes generated from assets/brand/tokens.json, and
// the window icon embedded from assets/brand/png/app-icon-512.png. Code outside
// this area takes brand colors from here instead of spelling them.
namespace cuervo::brand {

enum class Theme { Light, Dark };

const ThemeColors& colors(Theme theme);
std::string_view theme_name(Theme theme);
// "light" / "dark"; false for anything else.
bool parse_theme(std::string_view text, Theme& out);

// "#RRGGBB" (alpha dropped), e.g. to fill an SVG's currentColor.
std::string to_hex(rhi::Color color);
// The same color with alpha `a`.
constexpr rhi::Color with_alpha(rhi::Color c, float a) { return {c.r, c.g, c.b, a}; }
// Linear blend in sRGB, as the renderer blends (DESIGN.md 7.2 "Color").
constexpr rhi::Color mix(rhi::Color a, rhi::Color b, float t) {
    return {a.r + (b.r - a.r) * t, a.g + (b.g - a.g) * t, a.b + (b.b - a.b) * t, a.a + (b.a - a.a) * t};
}

// The app icon PNG (512x512, the two-tone mark on a Raven tile).
std::span<const std::uint8_t> app_icon_png();

} // namespace cuervo::brand
